 37	function isRecord(value: unknown): value is Record<string, unknown> {
 38	  return typeof value === "object" && value !== null && !Array.isArray(value);
 39	}
 40	
 41	function finiteNonNegative(value: unknown): number {
 42	  return typeof value === "number" && Number.isFinite(value) && value >= 0 ? value : 0;
 43	}
 44	
 45	function stringArray(value: unknown): string[] {
