 53	/**
 54	 * Validate and normalize the public models.dev provider catalog. Only models
 55	 * that the native chat transports can actually call are exposed.
 56	 */
 57	export function parseModelsDevCatalog(payload: unknown): CatalogModel[] {
 58	  if (!isRecord(payload)) throw new Error("models.dev returned an invalid catalog.");
 59	  const models: CatalogModel[] = [];
 60	
 61	  for (const [providerKey, providerValue] of Object.entries(payload)) {
 62	    if (!MODELS_DEV_PROVIDERS.has(providerKey as ProviderId) || !isRecord(providerValue)) continue;
 63	    const provider = providerKey as ProviderId;
 64	    const providerLabel = typeof providerValue.name === "string"
 65	      ? providerValue.name
 66	      : providerDefinition(provider).label;
 67	    if (!isRecord(providerValue.models)) continue;
 68	
 69	    for (const [recordKey, modelValue] of Object.entries(providerValue.models)) {
 70	      if (!isRecord(modelValue)) continue;
 71	      const id = typeof modelValue.id === "string" && modelValue.id.trim() ? modelValue.id.trim() : recordKey.trim();
 72	      if (!id) continue;
 73	      const modalities = isRecord(modelValue.modalities) ? modelValue.modalities : {};
 74	      const inputs = stringArray(modalities.input);
 75	      const outputs = stringArray(modalities.output);
 76	      const limits = isRecord(modelValue.limit) ? modelValue.limit : {};
 77	      const contextWindow = finiteNonNegative(limits.context);
 78	
 79	      // Image, speech, embedding, and other non-chat entries share the public
 80	      // catalog. The mobile Tutor can only use models that produce text.
 81	      if (!outputs.includes("text") || contextWindow <= 0) continue;
 82	
 83	      models.push({
 84	        key: catalogKey(provider, id),
 85	        provider,
 86	        providerLabel,
 87	        id,
 88	        name: typeof modelValue.name === "string" && modelValue.name.trim() ? modelValue.name.trim() : id,
 89	        description: typeof modelValue.description === "string" ? modelValue.description.trim() : "",
 90	        reasoning: modelValue.reasoning === true,
 91	        vision: inputs.includes("image"),
 92	        contextWindow,
 93	        maxOutputTokens: finiteNonNegative(limits.output),
 94	        source: "models.dev",
 95	      });
 96	    }
 97	  }
 98	
 99	  if (models.length === 0) throw new Error("models.dev returned no compatible chat models.");
100	  return dedupeModels(models).sort(compareModels);
101	}
