103	export function modelHasCapabilities(
104	  model: CatalogModel,
105	  capabilities: readonly ModelCapabilityFilter[],
106	): boolean {
107	  return capabilities.every((capability) => {
108	    if (capability === "thinking") return model.reasoning;
109	    if (capability === "vision") return model.vision;
110	    return model.contextWindow >= LONG_CONTEXT_THRESHOLD;
111	  });
112	}
