114	export function filterCatalogModels(
115	  models: readonly CatalogModel[],
116	  query: string,
117	  providers: readonly ProviderId[],
118	  capabilities: readonly ModelCapabilityFilter[],
119	): CatalogModel[] {
120	  const normalized = query.trim().toLowerCase();
121	  return models.filter((model) => {
122	    if (providers.length > 0 && !providers.includes(model.provider)) return false;
123	    if (!modelHasCapabilities(model, capabilities)) return false;
124	    if (!normalized) return true;
125	    return `${model.name} ${model.id} ${model.provider} ${model.providerLabel}`.toLowerCase().includes(normalized);
126	  });
127	}
