176	    for (let match = EVENT_SEPARATOR.exec(buffer); match; match = EVENT_SEPARATOR.exec(buffer)) {
177	      const rawEvent = buffer.slice(0, match.index);
178	      buffer = buffer.slice(match.index + match[0].length);
179	      const data = rawEvent
