 15	export function createForkedSession(source: ChatSession, options: ForkOptions = {}): ChatSession {
 16	  const now = options.now ?? Date.now();
 17	  let messages = source.messages;
 18	  if (options.throughMessageId) {
 19	    const forkIndex = source.messages.findIndex((message) => message.id === options.throughMessageId);
 20	    if (forkIndex < 0) throw new Error("The selected fork point is no longer in this lesson.");
 21	    messages = source.messages.slice(0, forkIndex + 1);
 22	  }
 23	
 24	  const createMessageId = options.createMessageId ?? (() => createId("message"));
 25	  const titleBase = source.title === "New lesson"
 26	    ? "Untitled lesson"
 27	    : source.title.replace(/^Branch · /, "");
 28	
 29	  return {
 30	    id: options.createSessionId?.() ?? createId("session"),
 31	    title: `Branch · ${titleBase}`,
 32	    createdAt: now,
 33	    updatedAt: now,
 34	    messages: messages.map((message): ChatMessage => ({ ...message, id: createMessageId() })),
 35	    parentSessionId: source.id,
 36	    forkedFromMessageId: options.throughMessageId,
 37	    forkedAt: now,
 38	  };
 39	}
