 41	/** Parent-first session ordering with stable, bounded indentation metadata. */
 42	export function buildSessionTreeRows(sessions: readonly ChatSession[]): SessionTreeRow[] {
 43	  const byId = new Map(sessions.map((session) => [session.id, session]));
 44	  const children = new Map<string, ChatSession[]>();
 45	  const roots: ChatSession[] = [];
 46	  const byUpdated = (left: ChatSession, right: ChatSession) => right.updatedAt - left.updatedAt;
 47	
 48	  for (const session of sessions) {
 49	    if (session.parentSessionId && byId.has(session.parentSessionId) && session.parentSessionId !== session.id) {
 50	      const siblings = children.get(session.parentSessionId) ?? [];
 51	      siblings.push(session);
 52	      children.set(session.parentSessionId, siblings);
 53	    } else {
 54	      roots.push(session);
 55	    }
 56	  }
 57	  roots.sort(byUpdated);
 58	  for (const siblings of children.values()) siblings.sort(byUpdated);
 59	
 60	  const rows: SessionTreeRow[] = [];
 61	  const visited = new Set<string>();
 62	  const visit = (session: ChatSession, depth: number) => {
 63	    if (visited.has(session.id)) return;
 64	    visited.add(session.id);
 65	    rows.push({ session, depth });
 66	    for (const child of children.get(session.id) ?? []) visit(child, depth + 1);
 67	  };
 68	  for (const root of roots) visit(root, 0);
 69	  // Malformed cycles stay visible instead of disappearing from the browser.
 70	  for (const session of [...sessions].sort(byUpdated)) visit(session, 0);
 71	  return rows;
 72	}
