 74	export function parentSessionTitle(session: ChatSession, sessions: readonly ChatSession[]): string | null {
 75	  if (!session.parentSessionId) return null;
 76	  return sessions.find((candidate) => candidate.id === session.parentSessionId)?.title ?? "Deleted original";
 77	}
