 80	/** A soft pulsing block that marks where the next token will land. */
 81	function StreamingCaret() {
 82	  const styles = createStyles(useKeatingTheme());
 83	  const opacity = useRef(new Animated.Value(0.25)).current;
 84	  const [reduceMotion, setReduceMotion] = useState(false);
 85	
 86	  useEffect(() => {
 87	    void AccessibilityInfo.isReduceMotionEnabled().then(setReduceMotion);
 88	    const subscription = AccessibilityInfo.addEventListener("reduceMotionChanged", setReduceMotion);
 89	    return () => subscription.remove();
 90	  }, []);
 91	
 92	  useEffect(() => {
 93	    if (reduceMotion) {
 94	      opacity.setValue(1);
 95	      return undefined;
 96	    }
 97	    const loop = Animated.loop(
 98	      Animated.sequence([
 99	        Animated.timing(opacity, { toValue: 1, duration: 520, useNativeDriver: true }),
100	        Animated.timing(opacity, { toValue: 0.25, duration: 520, useNativeDriver: true }),
101	      ]),
102	    );
103	    loop.start();
104	    return () => loop.stop();
105	  }, [opacity, reduceMotion]);
106	
107	  return <Animated.View accessibilityLabel="Keating is responding" style={[styles.caret, { opacity }]} />;
108	}
