 33	export async function refreshModelsDevCatalog(
 34	  fetchImpl: typeof fetch = fetch,
 35	  options: { signal?: AbortSignal; timeoutMs?: number } = {},
 36	): Promise<CatalogModel[]> {
 37	  const controller = new AbortController();
 38	  const timeoutMs = options.timeoutMs ?? 30_000;
 39	  const abortFromCaller = () => controller.abort();
 40	  options.signal?.addEventListener("abort", abortFromCaller, { once: true });
 41	  const timeout = setTimeout(() => controller.abort(), timeoutMs);
 42	  try {
 43	    const response = await fetchImpl(MODELS_DEV_CATALOG_URL, {
 44	      headers: { Accept: "application/json" },
 45	      signal: controller.signal,
 46	    });
 47	    if (!response.ok) throw new Error(`models.dev refresh failed (HTTP ${response.status}).`);
 48	    const models = parseModelsDevCatalog(await response.json());
 49	    const cache: CachedCatalog = { updatedAt: Date.now(), models };
 50	    await AsyncStorage.setItem(CATALOG_CACHE_KEY, JSON.stringify(cache));
 51	    return models;
 52	  } catch (error) {
 53	    if (controller.signal.aborted && !options.signal?.aborted) {
 54	      throw new Error("models.dev refresh timed out. Check the connection and retry.");
 55	    }
 56	    throw error;
 57	  } finally {
 58	    clearTimeout(timeout);
 59	    options.signal?.removeEventListener("abort", abortFromCaller);
 60	  }
 61	}
