 37	const MODELS_DEV_PROVIDERS = new Set<ModelsDevProviderId>(["openai", "anthropic", "google", "openrouter"]);
 38	
 39	const TRANSPORT_INCOMPATIBLE_ID_PATTERNS: Readonly<Record<ModelsDevProviderId, readonly RegExp[]>> = {
 40	  openai: [/embedding/i, /realtime/i, /transcri/i, /whisper/i, /\btts\b/i, /moderation/i, /image/i, /audio/i],
 41	  anthropic: [],
 42	  google: [/embedding/i, /(?:^|[-/])live(?:[-/]|$)/i, /image/i, /lyria/i, /robotics/i, /deep-research/i],
 43	  openrouter: [/embedding/i, /realtime/i, /transcri/i, /whisper/i, /(?:^|[-/])tts(?:[-/]|$)/i, /moderation/i, /image/i, /audio/i],
 44	};
