 46	function isRecord(value: unknown): value is Record<string, unknown> {
 47	  return typeof value === "object" && value !== null && !Array.isArray(value);
 48	}
 49	
 50	function finiteNonNegative(value: unknown): number {
 51	  return typeof value === "number" && Number.isFinite(value) && value >= 0 ? value : 0;
 52	}
 53	
 54	function stringArray(value: unknown): string[] {
 55	  return Array.isArray(value) ? value.filter((entry): entry is string => typeof entry === "string") : [];
 56	}
 57	
 58	function catalogKey(provider: ProviderId, modelId: string): string {
 59	  return `${provider}::${modelId}`;
 60	}
 61	
 62	export function isNativeTransportCompatible(provider: ModelsDevProviderId, modelId: string): boolean {
 63	  return !TRANSPORT_INCOMPATIBLE_ID_PATTERNS[provider].some((pattern) => pattern.test(modelId));
 64	}
