 66	/**
 67	 * Validate and normalize the public models.dev provider catalog. Only models
 68	 * that the native chat transports can actually call are exposed.
 69	 */
 70	export function parseModelsDevCatalog(payload: unknown): CatalogModel[] {
 71	  if (!isRecord(payload)) throw new Error("models.dev returned an invalid catalog.");
 72	  const models: CatalogModel[] = [];
 73	
 74	  for (const [providerKey, providerValue] of Object.entries(payload)) {
 75	    if (!MODELS_DEV_PROVIDERS.has(providerKey as ModelsDevProviderId) || !isRecord(providerValue)) continue;
 76	    const provider = providerKey as ModelsDevProviderId;
 77	    const providerLabel = typeof providerValue.name === "string"
 78	      ? providerValue.name
 79	      : providerDefinition(provider).label;
 80	    if (!isRecord(providerValue.models)) continue;
 81	
 82	    for (const [recordKey, modelValue] of Object.entries(providerValue.models)) {
 83	      if (!isRecord(modelValue)) continue;
 84	      const id = typeof modelValue.id === "string" && modelValue.id.trim() ? modelValue.id.trim() : recordKey.trim();
 85	      if (!id) continue;
 86	      const modalities = isRecord(modelValue.modalities) ? modelValue.modalities : {};
 87	      const inputs = stringArray(modalities.input);
 88	      const outputs = stringArray(modalities.output);
 89	      const limits = isRecord(modelValue.limit) ? modelValue.limit : {};
 90	      const contextWindow = finiteNonNegative(limits.context);
 91	
 92	      // Image, speech, embedding, and other non-chat entries share the public
 93	      // catalog. The mobile Tutor can only use models that produce text.
 94	      if (!outputs.includes("text") || contextWindow <= 0 || !isNativeTransportCompatible(provider, id)) continue;
 95	
 96	      models.push({
 97	        key: catalogKey(provider, id),
 98	        provider,
 99	        providerLabel,
100	        id,
101	        name: typeof modelValue.name === "string" && modelValue.name.trim() ? modelValue.name.trim() : id,
102	        description: typeof modelValue.description === "string" ? modelValue.description.trim() : "",
103	        reasoning: modelValue.reasoning === true,
104	        vision: inputs.includes("image"),
105	        contextWindow,
106	        maxOutputTokens: finiteNonNegative(limits.output),
107	        source: "models.dev",
108	      });
109	    }
110	  }
111	
112	  if (models.length === 0) throw new Error("models.dev returned no compatible chat models.");
113	  return dedupeModels(models).sort(compareModels);
114	}
115	
116	export function modelHasCapabilities(
117	  model: CatalogModel,
118	  capabilities: readonly ModelCapabilityFilter[],
119	): boolean {
120	  return capabilities.every((capability) => {
121	    if (capability === "thinking") return model.reasoning;
122	    if (capability === "vision") return model.vision;
123	    return model.contextWindow >= LONG_CONTEXT_THRESHOLD;
124	  });
125	}
126	
127	export function filterCatalogModels(
128	  models: readonly CatalogModel[],
129	  query: string,
130	  providers: readonly ProviderId[],
131	  capabilities: readonly ModelCapabilityFilter[],
132	): CatalogModel[] {
133	  const normalized = query.trim().toLowerCase();
134	  return models.filter((model) => {
135	    if (providers.length > 0 && !providers.includes(model.provider)) return false;
136	    if (!modelHasCapabilities(model, capabilities)) return false;
137	    if (!normalized) return true;
138	    return `${model.name} ${model.id} ${model.provider} ${model.providerLabel}`.toLowerCase().includes(normalized);
139	  });
140	}
141	
142	export function catalogSections(
143	  models: readonly CatalogModel[],
144	  recentKeys: readonly string[],
145	  includeRecents: boolean,
146	): CatalogSections {
147	  const recentSet = new Set(includeRecents ? recentKeys : []);
148	  return {
149	    recent: models.filter((model) => recentSet.has(model.key)),
150	    cloud: models.filter((model) => model.source !== "custom" && !recentSet.has(model.key)),
151	    custom: models.filter((model) => model.source === "custom" && !recentSet.has(model.key)),
152	  };
153	}
154	
155	export function customCatalogModel(settings: ProviderSettings): CatalogModel | null {
156	  if (settings.provider !== "custom" || !settings.model.trim()) return null;
157	  return {
158	    key: catalogKey("custom", settings.model.trim()),
159	    provider: "custom",
160	    providerLabel: "Custom",
161	    id: settings.model.trim(),
162	    name: settings.model.trim(),
163	    description: settings.baseUrl,
164	    reasoning: false,
165	    vision: false,
166	    contextWindow: 0,
167	    maxOutputTokens: 0,
168	    source: "custom",
169	  };
170	}
171	
172	export function selectedProviderSettings(current: ProviderSettings, model: CatalogModel): ProviderSettings {
173	  return {
174	    provider: model.provider,
175	    model: model.id,
176	    baseUrl: model.provider === "custom" ? current.baseUrl : providerDefinition(model.provider).defaultBaseUrl,
177	    temperature: current.temperature,
178	  };
179	}
180	
181	export function mergeCatalogModels(...groups: ReadonlyArray<readonly CatalogModel[]>): CatalogModel[] {
182	  return dedupeModels(groups.flat()).sort(compareModels);
183	}
184	
185	function dedupeModels(models: readonly CatalogModel[]): CatalogModel[] {
186	  return Array.from(new Map(models.map((model) => [model.key, model])).values());
187	}
188	
189	function compareModels(left: CatalogModel, right: CatalogModel): number {
190	  return left.providerLabel.localeCompare(right.providerLabel) || left.name.localeCompare(right.name);
191	}
