 15	export function Button({
 16	  children,
 17	  onPress,
 18	  disabled = false,
 19	  loading = false,
 20	  variant = "primary",
 21	  compact = false,
 22	  accessibilityLabel,
 23	  style,
 24	}: ButtonProps) {
 25	  const theme = useKeatingTheme();
 26	  const styles = createStyles(theme);
 27	  const { colors } = theme;
 28	  const inactive = disabled || loading;
 29	  return (
 30	    <Pressable
 31	      accessibilityRole="button"
 32	      accessibilityLabel={accessibilityLabel}
 33	      accessibilityState={{ disabled: inactive, busy: loading }}
 34	      disabled={inactive}
 35	      onPress={onPress}
 36	      style={({ pressed }) => [
 37	        styles.base,
 38	        compact ? styles.compact : styles.regular,
 39	        styles[variant],
 40	        pressed && !inactive ? styles[`${variant}Pressed`] : null,
 41	        inactive ? styles.disabled : null,
 42	        style,
 43	      ]}
 44	    >
 45	      {loading ? (
 46	        <ActivityIndicator size="small" color={variant === "primary" ? colors.primaryInk : colors.text} />
 47	      ) : (
 48	        <Text style={[styles.label, variant === "primary" ? styles.primaryLabel : styles.defaultLabel]}>
 49	          {children}
 50	        </Text>
 51	      )}
 52	    </Pressable>
 53	  );
 54	}
